content.text:
            if not isinstance(tok, str):
                raise WireError('E_SCHEMA')
            if tok not in service_set:
                raise WireError('E_SCHEMA')
        if len(path) > stats.max_pathlen:
            stats.max_pathlen = len(path)
        stats.atoms.add((op, tuple(path)))
    elif op == 'not':
        if set(e.keys()) != {'op', 'arg'}:
            raise WireError('E_SCHEMA')
        expr_schema(e['arg'], service_set, stats)
    elif op == 'and' or op == 'or':
        if set(e.keys()) != {'op', 'args'}:
            raise WireError('E_SCHEMA')
        args = e['args']
        if not isinstance(args, list):
            raise WireError('E_SCHEMA')
        if len(args) > stats.max_args:
            stats.max_args = len(args)
        for a in args:
            expr_schema(a, service_set, stats)
    else:
        raise WireError('E_SCHEMA')


def validate_request(data):
    check_unicode(data)
    if not isinstance(data, dict):
        raise WireError('E_SCHEMA')
    if set(data.keys()) != {'services', 'rules', 'queries'}:
        raise WireError('E_SCHEMA')
    services = data['services']
    rules = data['rules']
    queries = data['queries']

    # ---- schema ----
    if not isinstance(services, list):
        raise WireError('E_SCHEMA')
    seen = set()
    for s in services:
        if not isinstance(s, str):
            raise WireError('E_SCHEMA')
        if s == '':
            raise WireError('E_SCHEMA')
        if s in seen:
            raise WireError('E_SCHEMA')
        seen.add(s)
    service_set = seen

    if not isinstance(rules, list):
        raise WireError('E_SCHEMA')
    stats = Stats()
    for rule in rules:
        if not isinstance(rule, dict):
            raise WireError('E_SCHEMA')
        if set(rule.keys()) != {'action', 'when'}:
            raise WireError('E_SCHEMA')
        act = rule['action']
        if not isinstance(act, str) or act not in ('allow', 'drop'):
            raise WireError('E_SCHEMA')
        expr_schema(rule['when'], service_set, stats)

    if not isinstance(queries, list):
        raise WireError('E_SCHEMA')
    for q in queries:
        if not isinstance(q, list):
            raise WireError('E_SCHEMA')
        for tok in q:
            if not isinstance(tok, str):
                raise WireError('E_SCHEMA')
            if tok not in service_set:
                raise WireError('E_SCHEMA')

    # ---- size limits ----
    if len(services) > 24:
        raise WireError('E_LIMIT')
    for s in services:
        if len(s) > 64:
            raise WireError('E_LIMIT')
    if len(rules) > 32:
        raise WireError('E_LIMIT')
    if len(queries) > 256:
        raise WireError('E_LIMIT')
    total_q = 0
    for q in queries:
        if len(q) > 4096:
            raise WireError('E_LIMIT')
        total_q += len(q)
    if total_q > 16384:
        raise WireError('E_LIMIT')
    if stats.nodes > 256:
        raise WireError('E_LIMIT')
    if stats.max_args > 32:
        raise WireError('E_LIMIT')
    if stats.max_pathlen > 16:
        raise WireError('E_LIMIT')
    if len(stats.atoms) > 10:
        raise WireError('E_LIMIT')

    return services, rules, queries, stats


# ---------------------------------------------------------------------------
# Atomic monitors
# ---------------------------------------------------------------------------

def build_prefix_table(pat):
    m = len(pat)
    pi = [0] * m
    k = 0
    for i in range(1, m):
        while k > 0 and pat[i] != pat[k]:
            k = pi[k - 1]
        if pat[i] == pat[k]:
            k += 1
        pi[i] = k
    return pi


def build_monitor(op, pat, A):
    """Return (init_state, true_state, transition_table)."""
    m = len(pat)
    if op == 'match':
        fail = m + 1
        n = m + 2
        trans = [[fail] * A for _ in range(n)]
        for k in range(m):
            trans[k][pat[k]] = k + 1
        return 0, m, trans
    if op == 'startswith':
        fail = m + 1
        n = m + 2
        trans = [[fail] * A for _ in range(n)]
        for k in range(m):
            trans[k][pat[k]] = k + 1
        trans[m] = [m] * A
        return 0, m, trans
    # endswith / contains
    if m == 0:
        return 0, 0, [[0] * A]
    pi = build_prefix_table(pat)
    n = m + 1
    trans = [[0] * A for _ in range(n)]

    def step(k, c):
        while True:
            if k < m and pat[k] == c:
                return k + 1
            if k == 0:
                return 0
            k = pi[k - 1]

    if op == 'endswith':
        for k in range(n):
            row = trans[k]
            for c in range(A):
                row[c] = step(k, c)
        return 0, m, trans
    else:  # contains
        for k in range(m):
            row = trans[k]
            for c in range(A):
                row[c] = step(k, c)
        trans[m] = [m] * A
        return 0, m, trans


# ---------------------------------------------------------------------------
# Product construction & complexity check
# ---------------------------------------------------------------------------

COMPLEXITY_CAP = 20000


def build_product(atoms, service_index, A):
    monitors = []
    for op, path in atoms:
        pat = [service_index[t] for t in path]
        monitors.append(build_monitor(op, pat, A))

    natoms = len(monitors)
    init = tuple(mo[0] for mo in monitors)
    true_states = [mo[1] for mo in monitors]
    tables = [mo[2] for mo in monitors]

    state_id = {init: 0}
    states = [init]
    rows = []
    dq = deque([0])
    while dq:
        sid = dq.popleft()
        tup = states[sid]
        row = [0] * A
        for c in range(A):
            nt = tuple(tables[i][tup[i]][c] for i in range(natoms))
            j = state_id.get(nt)
            if j is None:
                j = len(states)
                if j >= COMPLEXITY_CAP:
                    raise WireError('E_COMPLEXITY')
                state_id[nt] = j
                states.append(nt)
                dq.append(j)
            row[c] = j
        rows.append(row)

    # accept per state
    accept = []
    for tup in states:
        truth = [tup[i] == true_states[i] for i in range(natoms)]
        accept.append(evaluate(global_tree, truth))
    return rows, accept


# ---------------------------------------------------------------------------
# Expression tree
# ---------------------------------------------------------------------------

# nodes are tuples:
#   ('const', bool)
#   ('atom', index)
#   ('not', child)
#   ('and', [children]) / ('or', [children])

def build_tree(e, atom_index):
    op = e['op']
    if op == 'true':
        return ('const', True)
    if op == 'false':
        return ('const', False)
    if op in ('match', 'startswith', 'endswith', 'contains'):
        return ('atom', atom_index[(op, tuple(e['path']))])
    if op == 'not':
        return ('not', build_tree(e['arg'], atom_index))
    if op == 'and':
        return ('and', [build_tree(a, atom_index) for a in e['args']])
    return ('or', [build_tree(a, atom_index) for a in e['args']])


def evaluate(node, truth):
    op = node[0]
    if op == 'const':
        return node[1]
    if op == 'atom':
        return truth[node[1]]
    if op == 'not':
        return not evaluate(node[1], truth)
    if op == 'and':
        for ch in node[1]:
            if not evaluate(ch, truth):
                return False
        return True
    # or
    for ch in node[1]:
        if evaluate(ch, truth):
            return True
    return False


global_tree = None


# ---------------------------------------------------------------------------
# DFA minimization (Hopcroft)
# ---------------------------------------------------------------------------

def hopcroft(n, A, trans, accept):
    if n <= 1:
        blocks = {0: set(range(n))}
        block_of = [0] * n
        return blocks, block_of

    # predecessor lists
    pred = [[[] for _ in range(n)] for _ in range(A)]
    for s in range(n):
        row = trans[s]
        for c in range(A):
            pred[c][row[c]].append(s)

    blocks = {}
    block_of = [0] * n
    nxt = [0]

    def new_block(S):
        bid = nxt[0]
        nxt[0] += 1
        blocks[bid] = S
        for s in S:
            block_of[s] = bid
        return bid

    acc = set(s for s in range(n) if accept[s])
    non = set(s for s in range(n) if not accept[s])
    if acc:
        new_block(acc)
    if non:
        new_block(non)

    Wd = deque()
    inW = set()
